import{_ as s,o as a,c as o,a2 as t}from"./chunks/framework.7R1OEGYz.js";const g=JSON.parse('{"title":"Sharing a session","description":"","frontmatter":{},"headers":[],"relativePath":"sharing.md","filePath":"sharing.md","lastUpdated":1793865691000}'),i={name:"sharing.md"};function r(n,e,h,l,d,c){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="sharing-a-session" tabindex="-1">Sharing a session <a class="header-anchor" href="#sharing-a-session" aria-label="Permalink to &quot;Sharing a session&quot;">​</a></h1><h2 id="history-of-a-shared-session" tabindex="-1">History of a shared session <a class="header-anchor" href="#history-of-a-shared-session" aria-label="Permalink to &quot;History of a shared session&quot;">​</a></h2><p>Everyone a session is shared with can read its whole conversation, not only what is still in the terminal. That covers people you shared it with by name, children of a shared session, sessions shared through a project, and share links — as Viewer or as Collaborator.</p><ul><li>Open the <strong>Workspace</strong> view of the shared session. It shows the newest messages first; use <strong>Load earlier messages</strong> to go back to the start of the conversation.</li><li>While the session runs, the conversation follows the agent live, as it does for the owner.</li><li>The history comes in pages of up to 500 messages, so a long session loads a page at a time.</li><li>Values only the owner may see are shown as <code>[redacted]</code>. Session secrets are hidden the same way they are for the owner.</li><li>Revoking a share, deleting a link or letting it expire takes effect on the next request. An open shared page then shows <em>This share link is invalid, expired, or revoked</em>.</li></ul><p>The same history is available to MCP clients that read a session shared with you.</p>',5)])])}const f=s(i,[["render",r]]);export{g as __pageData,f as default};
